package api

import ("encoding/json";"io";"net/http";"strings")
type AccountAPI struct { Service AccountService }
type AccountService interface { CreateAccount(AccountInput) (any,error); ListAccounts() (any,error) }
type AccountInput struct { Name string `json:"name"`; Type string `json:"type"`; Currency string `json:"currency"` }
func (a AccountAPI) Create(w http.ResponseWriter,r *http.Request){if w==nil||r==nil{return};if r.Method!=http.MethodPost{http.Error(w,"method not allowed",http.StatusMethodNotAllowed);return};if a.Service==nil{http.Error(w,"account service unavailable",http.StatusServiceUnavailable);return};if r.Body==nil{http.Error(w,"invalid request body",http.StatusBadRequest);return};var input AccountInput;dec:=json.NewDecoder(http.MaxBytesReader(w,r.Body,16<<10));if err:=dec.Decode(&input);err!=nil{http.Error(w,"invalid request body",http.StatusBadRequest);return};var extra any;if err:=dec.Decode(&extra);err!=io.EOF{http.Error(w,"invalid request body",http.StatusBadRequest);return};input.Name,input.Type,input.Currency=strings.TrimSpace(input.Name),strings.TrimSpace(input.Type),strings.TrimSpace(input.Currency);if len(input.Name)>256||len(input.Type)>64||len(input.Currency)>32{http.Error(w,"account field too long",http.StatusBadRequest);return};if input.Name==""||input.Type==""||input.Currency==""{http.Error(w,"name, type and currency are required",http.StatusBadRequest);return};result,err:=a.Service.CreateAccount(input);if err!=nil{http.Error(w,"account creation failed",http.StatusInternalServerError);return};w.Header().Set("Content-Type","application/json");w.WriteHeader(http.StatusCreated);_ = json.NewEncoder(w).Encode(result)}
func (a AccountAPI) List(w http.ResponseWriter,r *http.Request){if w==nil||r==nil{return};if r.Method!=http.MethodGet{http.Error(w,"method not allowed",http.StatusMethodNotAllowed);return};if a.Service==nil{http.Error(w,"account service unavailable",http.StatusServiceUnavailable);return};result,err:=a.Service.ListAccounts();if err!=nil{http.Error(w,"account lookup failed",http.StatusInternalServerError);return};w.Header().Set("Content-Type","application/json");_ = json.NewEncoder(w).Encode(result)}
